#!/usr/bin/env bash
# bin/coding-rules-check.sh — enforces WPMediaVerse-specific coding rules.
#
# Run via: composer coding-rules
#         (or directly: bash bin/coding-rules-check.sh)
#
# Each rule has its own check function. On violation the script appends a
# line to $VIOLATIONS_FILE and exits 1 at the end. Exit 0 = all rules pass.
#
# Generated by wp-plugin-onboard skill. Customize each check for your
# plugin's specific rules — the two below are the most-common patterns:
#   1. Native current_user_can() with a custom-ability slug (broken when
#      abilities have default_roles=[] — common in custom-RBAC plugins)
#   2. REST __return_true outside an explicit allowlist (security gate
#      against silently-public endpoints)

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

VIOLATIONS_FILE="$(mktemp)"
trap 'rm -f "$VIOLATIONS_FILE"' EXIT

violation() {
    echo "✗ $*"
    echo "v" >> "$VIOLATIONS_FILE"
}
ok() { echo "✓ $*"; }
# known_gap: same visibility as violation(), but does NOT fail the overall exit
# code or block the pre-push hook. Use for a rule that is correct and real but
# has a known, currently-nonzero backlog being worked down incrementally (see
# Rule 2's original rollout). A rule stays here only as long as the backlog is
# actually shrinking release over release — a known_gap() that never empties is
# a rule nobody is honoring, which is worse than not having the rule.
known_gap() {
    echo "⚠ $*"
}
violations_count() { wc -l < "$VIOLATIONS_FILE" | tr -d ' '; }

# ------------------------------------------------------------------------------

# Rule 1: never use current_user_can() with a custom-ability slug.
# Architecture: if your plugin registers abilities with empty default_roles
# (common in custom RBAC), current_user_can('plugin/foo') returns false
# for everyone. The plugin's own Permission_Engine (or equivalent) is the
# only correct gate.
#
# Customize: replace mvs with your plugin's ability namespace.
check_no_native_cap_check_for_plugin_abilities() {
    local hits
    hits=$(grep -rEn "current_user_can\(\s*['\"]mvs/" "$PLUGIN_DIR/includes/" 2>/dev/null \
            | grep -vE "Permission_Engine|class-abilities\.php|/CHANGELOG|/tests/" \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 1 — current_user_can('mvs/...') outside Permission_Engine:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: route the check through your plugin's Permission_Engine."
    else
        ok "Rule 1 — no native cap checks for mvs/* abilities"
    fi
}

# Rule 2: REST permission_callback must not use the bare '__return_true'
# string outside the allowlist of intentionally-public controllers (auth,
# catalog, certificate verification, third-party webhooks).
#
# Customize: list every controller file that legitimately ships
# __return_true. Document the reason in audit/FEATURE_AUDIT.md §3.
check_unauthenticated_rest_allowlist() {
    # Allowlist populated 2026-05-01 (Item 5 triage). Every entry is
    # documented with a one-line block-comment in the controller file
    # explaining the verdict. Audit doc: action-audit-2026-05-01/SUMMARY.md
    # row "23 routes use permission_callback => __return_true. These are
    # public read endpoints" — re-validated end-to-end during deferred-item-5.
    local allowed_files=(
        # Public read endpoints (privacy enforced inside the query/repo layer)
        'UserController.php'         # /users/{id}, /users/{id}/media, /users/search — public profile + privacy-filtered media + directory search
        'AlbumController.php'        # GET /albums + GET /albums/{id} — privacy enforced at SQL/service layer
        'MediaController.php'        # GET /media + /view + /access + /group — privacy filter in handler SQL line 254-262
        'TagController.php'          # GET /tags + /tags/cloud — public taxonomy
        'CommentController.php'      # GET /comments — inherits parent media privacy
        'ActivityController.php'     # GET /feed + /users/{id}/activity — public-only at query layer
        'StatsController.php'        # GET /media/{id}/stats — aggregated counts only
        'ReactionController.php'     # GET /reactions — aggregated counts grouped by type
        'FollowController.php'       # GET /users/{id}/followers + /following — public follow graph
        # HMAC-signed credential / capability discovery
        'SignedUrlController.php'    # GET /serve — HMAC signature on URL is the credential (S3 pre-signed pattern)
        'Abilities.php'              # 4 discovery entries — readonly metadata, execute_callback=noop
        # Public app bootstrap reads (consumed pre-auth by the BuddyNext mobile app)
        'ConfigController.php'       # GET /app/config — public branding + feature flags, read before login by design
        'InterestsController.php'    # GET /app/interests — public onboarding catalog (the /me/interests routes are logged-in)
        'AuthController.php'         # POST /auth/app-password — first-credential mint, public by necessity; guards (owner switch, TLS, rate limits, suspension gate) live in Auth\AppCredentials
    )

    if [ ${#allowed_files[@]} -eq 0 ]; then
        # No allowlist defined — only flag if there are any __return_true uses.
        local hits
        hits=$(grep -rEn "['\"]__return_true['\"]" "$PLUGIN_DIR/includes/" 2>/dev/null \
                | grep -vE "/tests/|class-abilities\\.php" \
                | grep -vE ':[0-9]+:[[:space:]]*(//|#|\*)' || true)
        if [ -n "$hits" ]; then
            violation "Rule 2 — __return_true permission_callback found, no allowlist defined yet:"
            echo "$hits" | sed 's/^/    /'
            echo "    Fix: add the controller file to allowed_files[] in this script,"
            echo "         OR replace with a named permission method that returns true|WP_Error."
        else
            ok "Rule 2 — no __return_true REST callbacks"
        fi
        return
    fi

    local exclude_pattern
    exclude_pattern=$( IFS='|' ; echo "${allowed_files[*]}" )

    local hits
    hits=$(grep -rEn "['\"]__return_true['\"]" "$PLUGIN_DIR/includes/" 2>/dev/null \
            | grep -vE "$exclude_pattern" \
            | grep -vE ':[0-9]+:[[:space:]]*(//|#|\*)' \
            || true)

    if [ -n "$hits" ]; then
        violation "Rule 2 — __return_true on a non-allowlisted REST endpoint:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: replace with a named permission method that returns true|WP_Error,"
        echo "         OR add this controller to the allowlist + document in"
        echo "         audit/FEATURE_AUDIT.md §3 if the route is intentionally public."
    else
        ok "Rule 2 — REST __return_true usage is on the allowlist only"
    fi
}

# ------------------------------------------------------------------------------

# Rule 3: site-wide aggregate counts MUST go through AdminAggregatesService.
# Coding Rule #16 in CLAUDE.md: raw $wpdb->get_var() with SUM() / COUNT(*)
# against any mvs_* table is forbidden outside this service. Why: each ad-hoc
# query bypasses the cache layer, so optimizations only apply where someone
# remembered to wrap them. Centralising in AdminAggregatesService gives a
# single source of truth + uniform daily-TTL persistent cache.
check_no_raw_aggregate_queries_outside_service() {
    local hits
    hits=$(grep -rEn "get_var\([^)]*(SUM|COUNT)\([^)]*\)\s*FROM\s*\\\$wpdb->prefix\s*\.\s*['\"]mvs_|get_var\([^)]*(SUM|COUNT)\([^)]*\)\s*FROM\s*\\\$wpdb->prefix\s*\.\s*'mvs_|get_var\([^)]*\"SELECT\s+(SUM|COUNT)\([^)]*\)\s*FROM\s*\\\$wpdb->prefix" \
            "$PLUGIN_DIR/includes/" 2>/dev/null \
            | grep -vE "/Services/AdminAggregatesService\.php|/Services/StatsService\.php|/Admin/StatsPage\.php:.*--user_count|/CLI/Commands\.php:.*\\\$total_users" \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 3 — raw SUM/COUNT against mvs_* outside AdminAggregatesService:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: add a method to includes/Services/AdminAggregatesService.php"
        echo "         and call \$container->get('admin_aggregates')->that_method()."
        echo "         See CLAUDE.md Coding Rule #16 (cache backend by cardinality)."
    else
        ok "Rule 3 — admin aggregates routed through AdminAggregatesService"
    fi
}

# Rule 4: high-cardinality data MUST NOT live in transients/options.
# Coding Rule #16 in CLAUDE.md: any set_transient($key, ...) where $key is
# interpolated with a per-entity variable ($user_id, $media_id, etc.) is a
# wp_options bloat at scale. Use a custom mvs_* table or wp_cache_* with
# a wp_using_ext_object_cache() guard.
check_no_per_entity_transients() {
    local hits
    hits=$(grep -rEn "set_transient\(\s*['\"][^'\"]*\\\$(user_id|media_id|conversation_id|album_id|post_id|comment_id|term_id)" \
            "$PLUGIN_DIR/includes/" 2>/dev/null \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 4 — per-entity transient (pollutes wp_options at scale):"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: store in a custom mvs_* table OR use wp_cache_* gated by"
        echo "         wp_using_ext_object_cache(). See CLAUDE.md Coding Rule #16."
    else
        ok "Rule 4 — no per-entity transient keys"
    fi
}

# ------------------------------------------------------------------------------

# Rule 5: every REST `'per_page' => array(...)` entry MUST declare a 'maximum'.
# Phase 3E added missing caps (AccessController had no upper bound, letting
# a malicious client request per_page=999999). The grep is intentionally
# coarse — multi-line array() blocks where the per_page key opens and
# closes on different lines are flagged via a python pass against the
# raw source so that nested arrays don't confuse a regex.
check_rest_per_page_has_maximum() {
    local hits
    hits=$(python3 - "$PLUGIN_DIR" <<'PY'
import os, re, sys
plugin_dir = sys.argv[1]
controller_dir = os.path.join(plugin_dir, 'includes', 'REST', 'Controller')
violations = []
if os.path.isdir(controller_dir):
    for name in sorted(os.listdir(controller_dir)):
        if not name.endswith('.php'):
            continue
        path = os.path.join(controller_dir, name)
        src = open(path).read()
        for m in re.finditer(r"'per_page'\s*=>\s*array\(([^()]*?)\)\s*,", src, re.DOTALL):
            block = m.group(1)
            if "'maximum'" not in block:
                line_no = src[:m.start()].count('\n') + 1
                violations.append(f"{path}:{line_no} 'per_page' missing 'maximum'")
print('\n'.join(violations))
PY
2>/dev/null)
    if [ -n "$hits" ]; then
        violation "Rule 5 — REST per_page param without 'maximum' cap:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: add 'maximum' => apply_filters( 'mvs_rest_pagination_max', 100 )"
        echo "         alongside the 'default' / 'sanitize_callback' entries."
    else
        ok "Rule 5 — every REST per_page declares a 'maximum' cap"
    fi
}

# ------------------------------------------------------------------------------
# Rule 6: a refusal must not be returned through wp_send_json_success().
#
# Why this exists: the demo-data importer guarded on "does the site already
# have media?", refused, and reported the refusal with wp_send_json_success().
# The admin JS took its success path — redirect, no message — so from the
# owner's side the Import button did nothing at all. No error, no data, no clue.
#
# Every wiring layer was correct, so an action/wiring audit passed it cleanly:
# the button existed, the JS bound it, the wp_ajax_ handler was registered and
# the nonce matched. Only the SEMANTICS were wrong. This rule catches that
# specific shape — a success envelope whose message is plainly a refusal.
#
# Heuristic, deliberately narrow: it matches refusal words in the message of a
# success response. If a legitimate success message trips it, reword the
# message (users read it too) rather than widening the pattern.
check_no_refusal_reported_as_success() {
    local hits
    hits=$(grep -rniE "wp_send_json_success\([^)]*(already (exists|imported|seeded|running)|nothing to|cannot |can't |unable to|skipping|not allowed|denied|must .* first|delete .* first)" \
        "$PLUGIN_DIR/includes" "$PLUGIN_DIR"/*.php 2>/dev/null \
        | grep -v "/vendor/" || true)

    if [ -n "$hits" ]; then
        violation "Rule 6 — refusal returned via wp_send_json_success() (client cannot tell it failed):"
        echo "$hits" | sed 's/^/    /'
        echo "    -> use wp_send_json_error() so the UI can surface the reason."
    else
        ok "Rule 6 — no refusals disguised as success responses"
    fi
}

# ------------------------------------------------------------------------------

# Rule 7: no direct $wpdb query against mvs_media_index outside MediaRepository.
#
# Architecture invariant 6 (documented in MediaRepositoryInterface.php's docblock
# since 2.4.0, never mechanically enforced until now — see plan/document-library.md
# §24.1/§24.2): mvs_media_index is the authoritative media record and every read or
# write against it goes through Repository\MediaRepository, so caching, privacy
# filtering and query-shape changes apply everywhere at once instead of wherever
# someone remembered to duplicate them. A predicate-checking rule (Rule 3's SUM/COUNT
# grep, for example) does not catch this class of leak, which is exactly why one
# call site can still slip past every existing rule with a clean CI run.
#
# Detection: any $wpdb->{get_results|get_var|get_row|get_col|query|prepare}( ... )
# call whose argument contains the literal table name, matched across the whole
# call (not line-by-line, so multi-line prepare() calls are caught) via a Python
# pass — same approach as Rule 5, for the same reason: a regex anchored to one line
# misses the common case of a query string spanning several.
#
# Allowlist, each with an architectural reason, not a convenience exemption:
#   - Repository/MediaRepository.php      the repository itself
#   - Repository/MediaRepositoryInterface.php   docblock-only references, no queries
#   - Core/Migrator.php                   schema DDL + one-time backfills run before
#                                          the repository's assumptions about the
#                                          table's shape are safe to rely on
#   - Services/AdminAggregatesService.php the Rule-3-sanctioned home for site-wide
#                                          SUM/COUNT aggregates; routing its own
#                                          queries through the repository would only
#                                          relocate the SQL, not remove a leak
check_no_direct_media_index_query_outside_repository() {
    local hits
    hits=$(python3 "$SCRIPT_DIR/lib/detect-media-index-leaks.py" "$PLUGIN_DIR" 2>/dev/null)
    if [ -n "$hits" ]; then
        # known_gap(), not violation(): 31 pre-existing call sites across 12
        # files were confirmed real on 2026-08-11 (mutation-tested detector,
        # see bin/mutation-test-rule7.sh) and are being migrated incrementally
        # per plan/document-library.md §24.2 item 1. Making this a hard
        # violation() today would block every future `git push` on unrelated
        # work through the pre-push hook until all 31 are fixed in one sweep —
        # exactly the "no incremental patches" tension this rule is supposed
        # to resolve, not create. PROMOTE THIS TO violation() the moment this
        # list reaches zero, so a 32nd call site can never sneak back in.
        local count
        count=$(echo "$hits" | wc -l | tr -d ' ')
        known_gap "Rule 7 — direct \$wpdb query against mvs_media_index outside MediaRepository ($count known, tracked, not yet blocking):"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: add/use a MediaRepository method instead of querying the table"
        echo "         directly. See plan/document-library.md §24.2 item 1 for the"
        echo "         current known list and migration order. If this call site has"
        echo "         a genuine architectural reason to stay direct (like Migrator.php"
        echo "         or AdminAggregatesService.php), add it to the allowlist in"
        echo "         bin/lib/detect-media-index-leaks.py with a one-line reason."
        echo "    This is a known_gap(), not a violation() — it will not fail this"
        echo "    script or block a push until the list above is empty. Do not add"
        echo "    a 32nd line to it; new code must route through MediaRepository."
    else
        ok "Rule 7 — all mvs_media_index access routed through MediaRepository"
    fi
}

# ------------------------------------------------------------------------------

echo "=== WPMediaVerse coding-rules check ==="
echo "Plugin: $PLUGIN_DIR"
echo ""

check_no_native_cap_check_for_plugin_abilities
check_unauthenticated_rest_allowlist
check_no_raw_aggregate_queries_outside_service
check_no_per_entity_transients
check_rest_per_page_has_maximum
check_no_refusal_reported_as_success
check_no_direct_media_index_query_outside_repository

echo ""
COUNT=$(violations_count)
if [ "$COUNT" -eq 0 ]; then
    echo "All coding rules pass."
    exit 0
else
    echo "$COUNT violation(s) found. See CLAUDE.md \"Important patterns\"."
    exit 1
fi
